using System.Text;
using System.Text.RegularExpressions;

namespace QuickCode.Demo.Infrastructure.Integration.Workflows;

/// <summary>
/// Ensures values created by earlier HTTP steps are referenced via
/// <c>{{stepName.response.id}}</c>, not re-read from <c>{{input.*}}</c>.
/// Keep in sync with QuickCode.Dbml WorkflowDataflowValidator.
/// </summary>
public static class WorkflowDataflowValidator
{
    private static readonly Regex InputTokenRegex = new(
        @"\{\{\s*input\.([A-Za-z0-9_]+)\s*\}\}",
        RegexOptions.Compiled | RegexOptions.IgnoreCase);

    /// <summary>
    /// Step-name suffixes that mean "this HTTP call creates an entity".
    /// Bare POST is not enough (login/search POSTs would false-positive).
    /// </summary>
    private static readonly string[] CreateSuffixes =
    [
        "Insert", "Create", "Add", "Register"
    ];

    public static void Validate(Workflow workflow)
    {
        ArgumentNullException.ThrowIfNull(workflow);
        if (workflow.Steps is not { Count: > 0 })
            return;

        var producers = FindProducers(workflow).ToList();
        if (producers.Count == 0)
            return;

        var errors = new List<string>();

        foreach (var producer in producers)
        {
            var reachable = GetReachableStepNames(workflow, producer.StepName);
            foreach (var stepName in reachable)
            {
                if (!workflow.Steps.TryGetValue(stepName, out var step))
                    continue;

                var haystack = CollectStepText(step);
                foreach (Match match in InputTokenRegex.Matches(haystack))
                {
                    var inputField = match.Groups[1].Value;
                    if (!producer.OwnedInputFields.Contains(inputField))
                        continue;

                    errors.Add(
                        $"Step '{stepName}' uses '{{{{input.{inputField}}}}}' after create step '{producer.StepName}'. "
                        + $"Use '{{{{{producer.StepName}.response.id}}}}' (the id returned by that insert), "
                        + "not a host/Kafka input field.");
                }
            }
        }

        if (errors.Count > 0)
        {
            throw new InvalidOperationException(
                "Workflow dataflow validation failed:\n- " + string.Join("\n- ", errors.Distinct()));
        }
    }

    private sealed record Producer(string StepName, HashSet<string> OwnedInputFields);

    private static IEnumerable<Producer> FindProducers(Workflow workflow)
    {
        foreach (var (stepName, step) in workflow.Steps)
        {
            if (step.IsCoordinator || string.IsNullOrWhiteSpace(step.Url))
                continue;

            // Require create-like step name (…Insert/Create/Add/Register).
            // Do not treat every POST as a producer (auth login, search, etc.).
            if (!CreateSuffixes.Any(s =>
                    stepName.EndsWith(s, StringComparison.OrdinalIgnoreCase)))
            {
                continue;
            }

            var stem = DeriveEntityStem(stepName);
            if (string.IsNullOrWhiteSpace(stem))
                continue;

            yield return new Producer(stepName, BuildOwnedInputFields(stem));
        }
    }

    private static string DeriveEntityStem(string stepName)
    {
        var name = stepName.Trim();
        foreach (var suffix in CreateSuffixes)
        {
            if (name.EndsWith(suffix, StringComparison.OrdinalIgnoreCase) && name.Length > suffix.Length)
            {
                name = name[..^suffix.Length];
                break;
            }
        }

        return Singularize(ToCamel(name));
    }

    private static HashSet<string> BuildOwnedInputFields(string entityStem)
    {
        var set = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        if (string.IsNullOrWhiteSpace(entityStem))
            return set;

        set.Add(entityStem + "Id");
        set.Add(entityStem + "ID");
        set.Add(entityStem + "Key");
        return set;
    }

    private static HashSet<string> GetReachableStepNames(Workflow workflow, string fromStep)
    {
        var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var queue = new Queue<string>();

        void EnqueueTargets(string stepName)
        {
            if (!workflow.Steps.TryGetValue(stepName, out var step))
                return;

            foreach (var action in step.Transitions ?? [])
            {
                var target = action.Action?.Trim();
                if (string.IsNullOrWhiteSpace(target))
                    continue;
                if (IsTerminal(target))
                    continue;
                if (visited.Add(target))
                    queue.Enqueue(target);
            }

            if (step.IsParallelCoordinator)
            {
                foreach (var child in step.Parallel)
                {
                    if (visited.Add(child))
                        queue.Enqueue(child);
                }
            }

            if (step.IsForeachCoordinator && !string.IsNullOrWhiteSpace(step.ForeachItemStep))
            {
                if (visited.Add(step.ForeachItemStep!))
                    queue.Enqueue(step.ForeachItemStep!);
            }
        }

        EnqueueTargets(fromStep);
        while (queue.Count > 0)
            EnqueueTargets(queue.Dequeue());

        visited.Remove(fromStep);
        return visited;
    }

    private static bool IsTerminal(string action) =>
        action.Equals("success", StringComparison.OrdinalIgnoreCase)
        || action.Equals("end", StringComparison.OrdinalIgnoreCase)
        || action.Equals("fail", StringComparison.OrdinalIgnoreCase);

    private static string CollectStepText(Step step)
    {
        var sb = new StringBuilder();
        if (!string.IsNullOrWhiteSpace(step.Url))
            sb.AppendLine(step.Url);
        if (step.Headers != null)
        {
            foreach (var (_, value) in step.Headers)
                sb.AppendLine(value);
        }

        if (step.Body is { Count: > 0 })
            sb.AppendLine(step.Body.ToString(Newtonsoft.Json.Formatting.None));

        if (!string.IsNullOrWhiteSpace(step.Foreach))
            sb.AppendLine(step.Foreach);

        if (!string.IsNullOrWhiteSpace(step.Condition))
            sb.AppendLine(step.Condition);

        return sb.ToString();
    }

    private static string Singularize(string name)
    {
        if (string.IsNullOrWhiteSpace(name))
            return name;

        if (name.EndsWith("ies", StringComparison.OrdinalIgnoreCase) && name.Length > 3)
            return name[..^3] + (char.IsUpper(name[^3]) ? "Y" : "y");

        if (name.EndsWith("sses", StringComparison.OrdinalIgnoreCase))
            return name[..^2];

        if (name.EndsWith("ses", StringComparison.OrdinalIgnoreCase) && name.Length > 3)
            return name[..^2];

        if (name.EndsWith("s", StringComparison.OrdinalIgnoreCase)
            && !name.EndsWith("ss", StringComparison.OrdinalIgnoreCase)
            && !name.EndsWith("us", StringComparison.OrdinalIgnoreCase)
            && !name.EndsWith("status", StringComparison.OrdinalIgnoreCase)
            && name.Length > 1)
        {
            return name[..^1];
        }

        return name;
    }

    private static string ToCamel(string value)
    {
        var s = (value ?? string.Empty).Trim();
        if (s.Length == 0)
            return s;
        if (s.Length == 1)
            return s.ToLowerInvariant();
        return char.ToLowerInvariant(s[0]) + s[1..];
    }
}
